{
 "description": "InstanceV1 is the Schema for the InstanceV1s API. Manages a V1 DB instance resource within OpenStack.",
 "properties": {
  "spec": {
   "description": "InstanceV1Spec defines the desired state of InstanceV1",
   "properties": {
    "deletionPolicy": {
     "default": "Delete",
     "description": "DeletionPolicy specifies what will happen to the underlying external\nwhen this managed resource is deleted - either \"Delete\" or \"Orphan\" the\nexternal resource.\nThis field is planned to be deprecated in favor of the ManagementPolicies\nfield in a future release. Currently, both could be set independently and\nnon-default values would be honored if the feature flag is enabled.\nSee the design doc for more information: https://github.com/crossplane/crossplane/blob/499895a25d1a1a0ba1604944ef98ac7a1a71f197/design/design-doc-observe-only-resources.md?plain=1#L223",
     "enum": [
      "Orphan",
      "Delete"
     ],
     "type": "string"
    },
    "forProvider": {
     "properties": {
      "configurationId": {
       "description": "Configuration ID to be attached to the instance. Database instance\nwill be rebooted when configuration is detached.",
       "type": "string"
      },
      "database": {
       "description": "An array of database name, charset and collate. The database\nobject structure is documented below.",
       "items": {
        "properties": {
         "charset": {
          "description": "Database character set. Changing this creates a\nnew instance.",
          "type": "string"
         },
         "collate": {
          "description": "Database collation. Changing this creates a new instance.",
          "type": "string"
         },
         "name": {
          "description": "Database to be created on new instance. Changing this creates a\nnew instance.",
          "type": "string"
         }
        },
        "type": "object"
       },
       "type": "array"
      },
      "datastore": {
       "description": "An array of database engine type and version. The datastore\nobject structure is documented below. Changing this creates a new instance.",
       "properties": {
        "type": {
         "description": "Database engine type to be used in new instance. Changing this\ncreates a new instance.",
         "type": "string"
        },
        "version": {
         "description": "Version of database engine type to be used in new instance.\nChanging this creates a new instance.",
         "type": "string"
        }
       },
       "type": "object"
      },
      "flavorId": {
       "description": "The flavor ID of the desired flavor for the instance.\nChanging this creates new instance.",
       "type": "string"
      },
      "name": {
       "description": "A unique name for the resource.",
       "type": "string"
      },
      "network": {
       "description": "An array of one or more networks to attach to the\ninstance. The network object structure is documented below. Changing this\ncreates a new instance.",
       "items": {
        "properties": {
         "fixedIpV4": {
          "description": "Specifies a fixed IPv4 address to be used on this\nnetwork. Changing this creates a new instance.",
          "type": "string"
         },
         "fixedIpV6": {
          "description": "Specifies a fixed IPv6 address to be used on this\nnetwork. Changing this creates a new instance.",
          "type": "string"
         },
         "port": {
          "description": "The port UUID of a\nnetwork to attach to the instance. Changing this creates a new instance.",
          "type": "string"
         },
         "uuid": {
          "description": "The network UUID to\nattach to the instance. Changing this creates a new instance.",
          "type": "string"
         }
        },
        "type": "object"
       },
       "type": "array"
      },
      "region": {
       "description": "The region in which to create the db instance. Changing this\ncreates a new instance.",
       "type": "string"
      },
      "size": {
       "description": "Specifies the volume size in GB. Changing this creates new instance.",
       "type": "number"
      },
      "user": {
       "description": "An array of username, password, host and databases. The user\nobject structure is documented below.",
       "items": {
        "properties": {
         "databases": {
          "description": "A list of databases that user will have access to. If not specified,\nuser has access to all databases on th einstance. Changing this creates a new instance.",
          "items": {
           "type": "string"
          },
          "type": "array",
          "x-kubernetes-list-type": "set"
         },
         "host": {
          "description": "An ip address or % sign indicating what ip addresses can connect with\nthis user credentials. Changing this creates a new instance.",
          "type": "string"
         },
         "name": {
          "description": "Username to be created on new instance. Changing this creates a\nnew instance.",
          "type": "string"
         },
         "passwordSecretRef": {
          "description": "User's password. Changing this creates a\nnew instance.",
          "properties": {
           "key": {
            "description": "The key to select.",
            "type": "string"
           },
           "name": {
            "description": "Name of the secret.",
            "type": "string"
           },
           "namespace": {
            "description": "Namespace of the secret.",
            "type": "string"
           }
          },
          "required": [
           "key",
           "name",
           "namespace"
          ],
          "type": "object"
         }
        },
        "type": "object"
       },
       "type": "array"
      },
      "volumeType": {
       "description": "Specifies the volume type to use. If you want to\nspecify a volume type, you must also specify a volume size. Changing this\ncreates new instance.",
       "type": "string"
      }
     },
     "type": "object"
    },
    "initProvider": {
     "description": "THIS IS A BETA FIELD. It will be honored\nunless the Management Policies feature flag is disabled.\nInitProvider holds the same fields as ForProvider, with the exception\nof Identifier and other resource reference fields. The fields that are\nin InitProvider are merged into ForProvider when the resource is created.\nThe same fields are also added to the terraform ignore_changes hook, to\navoid updating them after creation. This is useful for fields that are\nrequired on creation, but we do not desire to update them after creation,\nfor example because of an external controller is managing them, like an\nautoscaler.",
