          "description": "The port UUID of a\nnetwork to attach to the instance. Changing this creates a new instance.",
          "type": "string"
         },
         "uuid": {
          "description": "The network UUID to\nattach to the instance. Changing this creates a new instance.",
          "type": "string"
         }
        },
        "type": "object"
       },
       "type": "array"
      },
      "region": {
       "description": "The region in which to create the db instance. Changing this\ncreates a new instance.",
       "type": "string"
      },
      "size": {
       "description": "Specifies the volume size in GB. Changing this creates new instance.",
       "type": "number"
      },
      "user": {
       "description": "An array of username, password, host and databases. The user\nobject structure is documented below.",
       "items": {
        "properties": {
         "databases": {
          "description": "A list of databases that user will have access to. If not specified,\nuser has access to all databases on th einstance. Changing this creates a new instance.",
          "items": {
           "type": "string"
          },
          "type": "array",
          "x-kubernetes-list-type": "set"
         },
         "host": {
          "description": "An ip address or % sign indicating what ip addresses can connect with\nthis user credentials. Changing this creates a new instance.",
          "type": "string"
         },
         "name": {
          "description": "Username to be created on new instance. Changing this creates a\nnew instance.",
          "type": "string"
         },
         "passwordSecretRef": {
          "description": "User's password. Changing this creates a\nnew instance.",
          "properties": {
           "key": {
            "description": "The key to select.",
            "type": "string"
           },
           "name": {
            "description": "Name of the secret.",
            "type": "string"
           },
           "namespace": {
            "description": "Namespace of the secret.",
            "type": "string"
           }
          },
          "required": [
           "key",
           "name",
           "namespace"
          ],
          "type": "object"
         }
        },
        "type": "object"
       },
       "type": "array"
      },
      "volumeType": {
       "description": "Specifies the volume type to use. If you want to\nspecify a volume type, you must also specify a volume size. Changing this\ncreates new instance.",
       "type": "string"
      }
     },
     "type": "object"
    },
    "managementPolicies": {
     "default": [
      "*"
     ],
     "description": "THIS IS A BETA FIELD. It is on by default but can be opted out\nthrough a Crossplane feature flag.\nManagementPolicies specify the array of actions Crossplane is allowed to\ntake on the managed and external resources.\nThis field is planned to replace the DeletionPolicy field in a future\nrelease. Currently, both could be set independently and non-default\nvalues would be honored if the feature flag is enabled. If both are\ncustom, the DeletionPolicy field will be ignored.\nSee the design doc for more information: https://github.com/crossplane/crossplane/blob/499895a25d1a1a0ba1604944ef98ac7a1a71f197/design/design-doc-observe-only-resources.md?plain=1#L223\nand this one: https://github.com/crossplane/crossplane/blob/444267e84783136daa93568b364a5f01228cacbe/design/one-pager-ignore-changes.md",
     "items": {
      "description": "A ManagementAction represents an action that the Crossplane controllers\ncan take on an external resource.",
      "enum": [
       "Observe",
       "Create",
       "Update",
       "Delete",
       "LateInitialize",
       "*"
      ],
      "type": "string"
     },
     "type": "array"
    },
    "providerConfigRef": {
     "default": {
      "name": "default"
     },
     "description": "ProviderConfigReference specifies how the provider that will be used to\ncreate, observe, update, and delete this managed resource should be\nconfigured.",
     "properties": {
      "name": {
       "description": "Name of the referenced object.",
       "type": "string"
      },
      "policy": {
       "description": "Policies for referencing.",
       "properties": {
        "resolution": {
         "default": "Required",
         "description": "Resolution specifies whether resolution of this reference is required.\nThe default is 'Required', which means the reconcile will fail if the\nreference cannot be resolved. 'Optional' means this reference will be\na no-op if it cannot be resolved.",
         "enum": [
          "Required",
          "Optional"
         ],
         "type": "string"
        },
        "resolve": {
         "description": "Resolve specifies when this reference should be resolved. The default\nis 'IfNotPresent', which will attempt to resolve the reference only when\nthe corresponding field is not present. Use 'Always' to resolve the\nreference on every reconcile.",
         "enum": [
          "Always",
          "IfNotPresent"
         ],
         "type": "string"
        }
       },
       "type": "object"
      }
     },
     "required": [
      "name"
     ],
