   "type": "object",
   "x-kubernetes-validations": [
    {
     "message": "spec.forProvider.datastore is a required parameter",
     "rule": "!('*' in self.managementPolicies || 'Create' in self.managementPolicies || 'Update' in self.managementPolicies) || has(self.forProvider.datastore) || (has(self.initProvider) \u0026\u0026 has(self.initProvider.datastore))"
    },
    {
     "message": "spec.forProvider.name is a required parameter",
     "rule": "!('*' in self.managementPolicies || 'Create' in self.managementPolicies || 'Update' in self.managementPolicies) || has(self.forProvider.name) || (has(self.initProvider) \u0026\u0026 has(self.initProvider.name))"
    },
    {
     "message": "spec.forProvider.size is a required parameter",
     "rule": "!('*' in self.managementPolicies || 'Create' in self.managementPolicies || 'Update' in self.managementPolicies) || has(self.forProvider.size) || (has(self.initProvider) \u0026\u0026 has(self.initProvider.size))"
    }
   ]
  }
